import numpy as np

def blocks_by_rows(grid, bg=0):
    """Return list of (row_start, row_end_exclusive) horizontal bands of non-background rows."""
    rows = [i for i, r in enumerate(grid) if any(v != bg for v in r)]
    bands, s, prev = [], None, None
    for i in rows:
        if prev is None or i != prev + 1:
            if s is not None:
                bands.append((s, prev + 1))
            s = i
        prev = i
    if s is not None:
        bands.append((s, prev + 1))
    return bands

def row_extent(row, bg=0):
    """Return (first, last) non-background column of a row, or (None, None)."""
    nz = [j for j, v in enumerate(row) if v != bg]
    return (nz[0], nz[-1]) if nz else (None, None)

def _missing_cells(src, dst, off, bg, W):
    """Cells where dst (dst[j] == src[j-off] relation) is background but the source pattern continues; only edge-hugging runs count."""
    se = row_extent(src, bg)
    de = row_extent(dst, bg)
    if se[0] is None or de[0] is None:
        return []
    js = [j for j in range(W)
          if dst[j] == bg and se[0] <= j - off <= se[1] and src[j - off] != bg]
    if not js:
        return []
    if all(j > de[1] for j in js) or all(j < de[0] for j in js):
        return js
    return []

def shift_copy_fill(grid, bg=0, fill=1):
    """Given two row-band copies of one pattern, one shifted a column and truncated, restore the truncated copy's missing cells in the fill color."""
    g = [list(row) for row in grid]
    W = len(g[0])
    bands = blocks_by_rows(g, bg)
    if len(bands) != 2:
        return g
    (a0, a1), (b0, b1) = bands
    if a1 - a0 != b1 - b0:
        return g
    A = g[a0:a1]; B = g[b0:b1]
    for off in (1, -1):
        ok = True
        for i in range(len(A)):
            a, b = A[i], B[i]
            aex, bex = row_extent(a, bg), row_extent(b, bg)
            for j, v in enumerate(b):
                k = j - off
                if v != bg and aex[0] is not None and aex[0] <= k <= aex[1] and a[k] != v:
                    ok = False
            for j, v in enumerate(a):
                k = j + off
                if v != bg and bex[0] is not None and bex[0] <= k <= bex[1] and b[k] != v:
                    ok = False
        if not ok:
            continue
        fills = []
        for i in range(len(A)):
            mA = _missing_cells(B[i], A[i], -off, bg, W)  # A[j] == B[j+off]
            mB = _missing_cells(A[i], B[i], off, bg, W)   # B[j] == A[j-off]
            if mA:
                fills.append((a0 + i, mA))
            if mB:
                fills.append((b0 + i, mB))
        if fills:
            for r, js in fills:
                for j in js:
                    g[r][j] = fill
            break
    return g

def infer_bg(grid):
    """Return the most frequent grid value (the background color)."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]
